from hypothesis import strategies as st

@st.composite
def gen(draw):
    n = draw(st.integers(2, 5))
    small = st.integers(1, 10)
    extreme = st.sampled_from([1, 2, 10, 1000, 10**6])
    A = draw(st.one_of(small, extreme))
    B = draw(st.one_of(small, extreme))
    C = draw(st.one_of(small, extreme))
    D = [[0] * n for _ in range(n)]
    for i in range(n):
        for j in range(i + 1, n):
            v = draw(st.one_of(small, st.just(1), st.sampled_from([10**6, 999999])))
            D[i][j] = v
            D[j][i] = v
    lines = [f"{n} {A} {B} {C}"]
    for i in range(n):
        lines.append(" ".join(map(str, D[i])))
    return "\n".join(lines) + "\n"

def validate(inp):
    try:
        t = inp.split()
        if len(t) < 4:
            return False
        n, A, B, C = map(int, t[:4])
        if not (2 <= n <= 1000):
            return False
        if not all(1 <= x <= 10**6 for x in (A, B, C)):
            return False
        vals = [int(x) for x in t[4:]]
        if len(vals) != n * n:
            return False
        D = [vals[i * n:(i + 1) * n] for i in range(n)]
        for i in range(n):
            if D[i][i] != 0:
                return False
            for j in range(n):
                if i != j:
                    if not (1 <= D[i][j] <= 10**6):
                        return False
                    if D[i][j] != D[j][i]:
                        return False
        return True
    except Exception:
        return False

def ref(inp):
    t = inp.split()
    n, A, B, C = map(int, t[:4])
    vals = [int(x) for x in t[4:]]
    D = [vals[i * n:(i + 1) * n] for i in range(n)]
    INF = float("inf")
    # states: (city, mode) mode 0 = company car, mode 1 = train
    dist = [[INF, INF] for _ in range(n)]
    dist[0][0] = 0
    changed = True
    while changed:
        changed = False
        # switching from car to train within the same city (free)
        for c in range(n):
            if dist[c][0] < dist[c][1]:
                dist[c][1] = dist[c][0]
                changed = True
        # travel edges
        for i in range(n):
            for j in range(n):
                if i == j:
                    continue
                d = D[i][j]
                # car
                if dist[i][0] + d * A < dist[j][0]:
                    dist[j][0] = dist[i][0] + d * A
                    changed = True
                # train from either mode
                tcost = d * B + C
                best_i = min(dist[i][0], dist[i][1])
                if best_i + tcost < dist[j][1]:
                    dist[j][1] = best_i + tcost
                    changed = True
    ans = min(dist[n - 1][0], dist[n - 1][1])
    return str(int(ans))
